mapper.select:
SELECT agent.id AS agentId, agent.agent_code AS agentCode, agent.agent_name AS agentName, agent.description AS agentDescription, agent.agent_type AS agentType, tenant.id AS tenantId, tenant.tenant_name AS tenantName, tenant.status AS tenantStatus, tenant.nacos_namespace_id AS tenantNacosNamespaceId, tenant.remark AS tenantRemark, ac.id AS agentConfigId, ac.sys_prompt_id AS sysPromptId, ac.model_id AS modelId, ac.max_iters AS maxIters, ac.permission_mode AS permissionMode, ac.compaction_enabled AS compactionEnabled, ac.trigger_messages AS triggerMessages, ac.keep_messages AS keepMessages, ac.trigger_tokens AS triggerTokens, ac.keep_tokens AS keepTokens, ac.tool_result_eviction_enabled AS toolResultEvictionEnabled, ac.memory_enable AS memoryEnable, ac.plan_mode_enabled AS planModeEnabled, ac.plan_file_directory AS planFileDirectory, ac.task_list_enabled AS taskListEnabled, ac.allow_shell_in_plan_mode AS allowShellInPlanMode, ac.state_store_type AS stateStoreType, model.config_name AS modelConfigName, model.provider_name AS providerName, model.protocol AS protocol, model.base_url AS baseUrl, model.api_key AS apiKey, model.model_name AS modelName, model.streaming AS streaming, model.thinking AS thinking, model.thinking_budget AS thinkingBudget, model.temperature AS temperature, model.top_p AS topP, model.max_tokens AS maxTokens, model.timeout_ms AS timeoutMs, model.max_attempts AS maxAttempts, model.fallback_model_config_id AS fallbackModelConfigId, model.status AS modelStatus, model.deleted AS modelDeleted, prompt.prompt_name AS promptName, prompt.sys_prompt AS sysPrompt FROM ai_agent agent INNER JOIN ai_agent_config ac ON ac.agent_id = agent.id AND ac.tenant_id = #{tenantId} AND ac.deleted = 0 LEFT JOIN sys_tenant tenant ON tenant.id = agent.tenant_id LEFT JOIN ai_agent_model model ON model.id = ac.model_id AND model.tenant_id = #{tenantId} LEFT JOIN ai_agent_sys_prompt prompt ON prompt.id = ac.sys_prompt_id AND prompt.tenant_id = #{tenantId} AND prompt.status = 1 AND prompt.deleted = 0 WHERE agent.id = #{agentId} AND agent.tenant_id = #{tenantId} AND agent.deleted = 0
AND ac.id = #{agentConfigId}
LIMIT 1
